16	/**
17	 * Game x location combos of the live matrix ("/malaysia-rust-server-hosting",
18	 * 615 of them) — rendered like the live page renders them: through the game
19	 * template (here: the design's game x location page, the same generated page
20	 * /minecraft-server-hosting/singapore uses) with the combo's honest location
21	 * framing on top.
22	 *
23	 * - Everything game-specific (tiers, configurator, mods, server types, DDoS,
24	 *   sizing, regions) is the game template's own real data (./games-page.ts
25	 *   gamePage), pinned to the region the LIVE adapter pins
26	 *   (buildGameLocationPreviewGame().deployRegion — lib/marketing/
27	 *   gameLocationLandings.ts), or unpinned (both regions offered) for the
28	 *   places it pins none (United States, North America, Canada).
29	 * - Everything location-specific is the live copy: the hero note is the
30	 *   location's `hub` sentence verbatim (the live "location note"), the chip is
31	 *   the live trust-strip label, and the FAQ leads with the live builder's FAQ
32	 *   (incl. its honest "is it hosted in X?" answer). No latency claims: the map
33	 *   shows straight-line km to the datacenter.
34	 */
35	
36	/** The live page's plan load for the family (active GamePlan rows + their
37	 *  base VPS plan, for the adapter's cards). */
38	async function familyPlans(family: string): Promise<{ rows: GamePlanRow[]; cards: PlanCard[] }> {
39	  const plans = await db.gamePlan.findMany({ where: { gameFamily: family, active: true }, orderBy: { sortOrder: "asc" }, include: { basePlan: true } });
40	  return {
41	    rows: plans.map((p) => ({ id: p.id, name: p.name, ramMB: p.ramMB, slots: p.slots, priceCents: p.priceCents, introPriceCents: p.introPriceCents })),
42	    cards: plans.map((p) => ({
43	      id: p.id, name: p.name, cpuCores: p.cpuCores, ramMB: p.ramMB, diskGB: p.diskGB, bandwidthTB: p.basePlan.bandwidthTB,
44	      priceCents: p.priceCents, storageTier: p.basePlan.storageTier, introMonthlyCents: p.introPriceCents, slots: p.slots,
45	    })),
46	  };
47	}
48	
49	/** A multi-zone place's clock shows its first-listed city (the hero's "Local
50	 *  time" chip is part of the design's game x location page). */
51	const FIRST_CITY_TZ: Record<string, string> = {
52	  "southeast-asia": "Asia/Kuala_Lumpur", indonesia: "Asia/Jakarta", "united-states": "America/New_York",
53	  "north-america": "America/New_York", canada: "America/Toronto", europe: "Europe/Berlin", australia: "Australia/Sydney",
54	};
55	
56	async function context(slug: string, combo: GameLocationCombo) {
57	  const regions = await copyRegions();
58	  const { rows, cards } = await familyPlans(combo.family);
59	  if (!rows.length) notFound(); // the family stopped selling: fail closed (the live builder would print a stale "$4.99")
60	  const built = buildGameLocationLanding(combo, rows);
61	  const pg = buildGameLocationPreviewGame(combo, cards);
62	  if (!pg) notFound();
63	  const region = pg.deployRegion ? regions.find((r) => r.code === pg.deployRegion) ?? null : null;
64	  return { regions, rows, built, pg, region, loc: combo.location, route: `/${slug}` };
65	}
66	
67	export async function gameLocationPage(slug: string, combo: GameLocationCombo): Promise<NxmLoad> {
68	  const c = await context(slug, combo);
69	  const { built, pg, region, loc } = c;
70	  const name = gameName(combo.family);
71	  // the game template's own page, pinned like the live adapter pins it
72	  const d = await gamePage(region ? { family: combo.family, region: region.code } : { family: combo.family }, !!region);
73	  const slots = { ...(d.slots ?? {}) };
74	
75	  // hero: honest location framing (live copy only)
76	  // datacenter places really host the server there; everywhere else the H1
77	  // names the audience, never a location (the chip + note say where it runs)
78	  const dcCity = region ? dcName(region).split(",")[0] : null;
79	  slots["hero.h1a"] = loc.presence === "datacenter" && dcCity ? `${name} servers in ${loc.name}.` : `${name} servers for`;
80	  slots["hero.h1b"] = loc.presence === "datacenter" && dcCity ? `Hosted in ${dcCity}.` : `${loc.audience} players.`;
81	  slots["hero.sub"] = loc.hub;
82	  slots["loc.flag"] = loc.flag ? `flag-${loc.flag}` : "";
83	  slots["loc.chip"] = `${name} · ${loc.name}`;
84	  slots["loc.bullet"] = pg.trustLatencyLabel ?? "";
85	  slots["loc.style"] = region && cityArt(region.code) ? `background-image:url(${cityArt(region.code)})` : "";
86	
87	  // where the players are: straight-line km from the location's cities
88	  const pts = placed(loc.nearby, c.regions);
89	  const map = mapHtml(pts, c.regions, region);
90	  slots["ping:html"] = pts.length
91	    ? `<section class="section gmp" id="ping" aria-labelledby="pg-title"><div class="container gmp-in"><div class="gmp-map${map.world ? " gmp-map--w" : ""}">${map.html}</div><div><h2 class="h2" id="pg-title">Where your players connect from</h2><p class="lede">${esc(`How far ${loc.name}’s players are from ${region ? `our ${dcName(region)} datacenter` : "our nearest datacenter"}. Closer usually means lower ping; real latency also depends on each player’s connection.`)} Hover a city to see its route.</p>${latHtml(pts, region, "glat")}</div></div></section>`
92	    : "";
93	
94	  // FAQ: the live builder's questions first, then the game template's own
95	  // (minus the two the live list already answers)
96	  const liveFaq = built.content.faq.map((f) => `<details><summary>${esc(f.q)}</summary><p>${esc(f.a)}</p></details>`);
97	  const tpl = [...(slots["faq:html"] ?? "").matchAll(/<details[^>]*>(<summary>([\s\S]*?)<\/summary>[\s\S]*?)<\/details>/g)]
98	    .filter((m) => !/mods|where are the servers/i.test(m[2]))
99	    .map((m) => `<details>${m[1]}</details>`);
100	  const faq = [...liveFaq, ...tpl].map((x, i) => (i === 0 ? x.replace("<details>", "<details open>") : x)).join("");
101	  slots["faq:html"] = `<section class="section" id="faq" aria-labelledby="faq-title" style="padding-top:0"><div class="container faq-wrap"><div><h2 class="h2" id="faq-title">Before you deploy</h2><p class="lede">The questions people ask right before they start.</p></div><div class="faq">${faq}</div></div></section>`;
102	
103	  // related: the live builder's links, as the design's link cards
104	  const cards = (built.content.related ?? []).map((r) => {
105	    const other = [...GAME_LOCATIONS_BY_SLUG.values()].find((l) => r.href === `/${l.slug}-${GAME_URL_SLUG[combo.family]}-server-hosting`);
106	    const ic = other ? `<span class="gl-ic gl-ic--f">${flag(other.flag || PLACE[other.slug]?.cc || "")}</span>` : `<span class="gl-ic"><span data-au-icon="${r.href === "/pricing" ? "card" : "game"}" data-grad></span></span>`;
107	    const small = other ? `${other.presence === "market" ? "Served from our datacenters" : other.presence === "network" ? "Near one of our datacenters" : "Real Nxeon datacenter"}` : r.href === "/pricing" ? "Every product, live prices" : r.href === "/game-servers" ? "Every game, one account" : "Every region and plan";
108	    return `<a class="gl-reg" href="${esc(link(r.href))}">${ic}<div><b>${esc(r.label)}</b><small>${esc(small)}</small></div><span class="gl-go">→</span></a>`;
109	  }).join("");
110	  slots["more:html"] = `<section class="section" id="more" style="padding-top:0"><div class="container glinks">${cards}</div></section>`;
111	
112	  const tiers = c.rows;
113	  const data = { ...(d.data as Record<string, unknown>), tz: PLACE[loc.slug]?.tz ?? FIRST_CITY_TZ[loc.slug] ?? (region ? (d.data as { tz?: string }).tz : null) ?? "UTC" };
114	  return {
115	    slots, data,
116	    jsonLd: [productLd(built.productName, built.content.sub, c.route,
117	      tiers.map((t) => ({ name: t.name, price: (planIntroMonthlyCents(t) ?? t.priceCents) / 100 })))],
118	    crumb: built.breadcrumbName,
119	    trail: [{ name: built.breadcrumbName, path: c.route }],
120	    particles: d.particles,
121	  };
122	}
123	
124	export async function gameLocationMeta(slug: string, combo: GameLocationCombo) {
125	  const c = await context(slug, combo);
126	  const art = gameArt(combo.family);
127	  return {
128	    title: c.built.metaTitle, description: c.built.metaDescription, crumb: c.built.breadcrumbName, type: "article" as const,
129	    ...(art.hero ? { image: art.hero } : {}),
130	  };
131	}
