159	/** Great-circle distance, km. */
160	export function distanceKm(a: { lat: number; lon: number }, b: { lat: number; lon: number }) {
161	  const D = Math.PI / 180, dLat = (b.lat - a.lat) * D, dLon = (b.lon - a.lon) * D;
162	  const h = Math.sin(dLat / 2) ** 2 + Math.cos(a.lat * D) * Math.cos(b.lat * D) * Math.sin(dLon / 2) ** 2;
163	  return 2 * 6371 * Math.asin(Math.sqrt(h));
164	}
