const { chromium } = require('/opt/nxeon/node_modules/playwright');
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1440, height: 1000 } });
  await page.goto('http://localhost:3910/game-servers', { waitUntil: 'networkidle', timeout: 60000 });
  const data = await page.evaluate(() => {
    const root = document.querySelector('.nxm-p');
    const sections = Array.from(root.querySelectorAll(':scope > section, .nxm-p > div > section'));
    const vw = window.innerWidth;
    return sections.map(s => {
      const r = s.getBoundingClientRect();
      const kid = s.firstElementChild;
      const kr = kid ? kid.getBoundingClientRect() : null;
      return {
        id: s.id || s.className,
        secLeft: r.left, secRight: vw - r.right,
        kidLeft: kr ? kr.left : null, kidRight: kr ? vw - kr.right : null,
        kidWidth: kr ? kr.width : null,
      };
    });
  });
  console.log(JSON.stringify(data, null, 1));
  await browser.close();
})();
" 2>&1

