(function scaling() {
  const CAPS = {
    1: 'Launch: a website on shared hosting, with your domain and email in the same account.',
    2: 'Grow: move your app onto a VPS and give your database its own server, next to your website and email.',
    3: 'Scale: run your app in more regions, closer to your users, with a replicated database.'
  };
  const svg = $('#scale-svg'), cap = $('#scale-cap-text'), seg = $('#stage-seg'), btns = $$('#stage-seg button');
  if (!svg) return;
  const set = n => { btns.forEach(x => x.setAttribute('aria-pressed', String(x.dataset.s === String(n)))); svg.dataset.stage = n; cap.textContent = CAPS[n]; };
  btns.forEach(b => b.addEventListener('click', () => { seg.classList.remove('auto'); set(+b.dataset.s); }));
  if (RM) { svg.pauseAnimations && svg.pauseAnimations(); return; }
  seg.classList.add('auto', 'hold');
  seg.addEventListener('animationend', () => { if (seg.classList.contains('auto')) set((+svg.dataset.stage % 3) + 1); });
  watch($('#scale-fig'), v => { seg.classList.toggle('hold', !v); if (svg.pauseAnimations) v ? svg.unpauseAnimations() : svg.pauseAnimations(); }, { threshold: 0.35 });
})();

