const fs = require('fs');

const HOME_CONTENT = '/opt/nxeon-wt-marketing-fixes/app/nxm/_home/content.ts';
const VPS_CONTENT = '/opt/nxeon-wt-marketing-fixes/app/nxm/_pages/vps/content.ts';
const HOME_SCRIPT = '/opt/nxeon-wt-marketing-fixes/app/nxm/_home/script.ts';
const VPS_SCRIPT = '/opt/nxeon-wt-marketing-fixes/app/nxm/_pages/vps/script.ts';

// ── 1. Move the HTML section ────────────────────────────────────────────────
let home = fs.readFileSync(HOME_CONTENT, 'utf8');
const bMarker = '<!-- ================= BUSINESS ================= -->';
const pMarker = '<!-- ================= PERFORMANCE ================= -->';
const bStart = home.indexOf(bMarker);
const pStart = home.indexOf(pMarker);
if (bStart === -1 || pStart === -1 || pStart <= bStart) throw new Error('markers not found as expected');
const rawSnippet = home.slice(bStart, pStart); // includes trailing "\n\n" before PERFORMANCE marker
if ((home.match(new RegExp(rawSnippet.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'g')) || []).length !== 1) {
  throw new Error('snippet not found exactly once in home content.ts');
}

const newHome = home.replace(rawSnippet, '');
fs.writeFileSync(HOME_CONTENT, newHome);
console.log('home content.ts: removed', rawSnippet.length, 'raw chars');

let vps = fs.readFileSync(VPS_CONTENT, 'utf8');
const faqAnchor = '<section class=\\"section\\" id=\\"faq\\"';
const faqIdx = vps.indexOf(faqAnchor);
if (faqIdx === -1) throw new Error('faq anchor not found in vps content.ts');
// rawSnippet already ends with "\n\n" (matching the file's blank-line-between-sections
// convention), so inserting it directly before the faq section's opening tag reproduces
// that same spacing on both sides.
const newVps = vps.slice(0, faqIdx) + rawSnippet + vps.slice(faqIdx);
fs.writeFileSync(VPS_CONTENT, newVps);
console.log('vps content.ts: inserted', rawSnippet.length, 'raw chars before #faq');

// ── 2. Move the "Scaling stages" JS behaviour ───────────────────────────────
let homeScript = fs.readFileSync(HOME_SCRIPT, 'utf8');
const sMarker = '/* ============ Scaling stages ============ */';
const sStart = homeScript.indexOf(sMarker);
if (sStart === -1) throw new Error('scaling stages marker not found in home script.ts');
const afterMarker = sStart + sMarker.length;
const closeMatch = homeScript.indexOf('})();', afterMarker);
if (closeMatch === -1) throw new Error('closing })(); not found');
const scriptEnd = closeMatch + 5;
const scriptSnippet = homeScript.slice(sStart, scriptEnd); // no trailing separator included

// Remove from home script.ts, along with the blank-line separators around it so we
// don't leave a double blank line.
const beforeSep = '\\n\\n';
const withLeadingSep = beforeSep + scriptSnippet;
if (homeScript.indexOf(withLeadingSep) === -1) throw new Error('leading-separator snippet not found in home script.ts');
const newHomeScript = homeScript.replace(withLeadingSep, '');
fs.writeFileSync(HOME_SCRIPT, newHomeScript);
console.log('home script.ts: removed', withLeadingSep.length, 'raw chars');

let vpsScript = fs.readFileSync(VPS_SCRIPT, 'utf8');
// Append at the end of the script, before the closing PAGE_SCRIPT quote+semicolon.
// PAGE_SCRIPT is stored as `export const PAGE_SCRIPT = "....";\n`
const tailMatch = vpsScript.match(/(";\n)$/);
if (!tailMatch) throw new Error('vps script.ts does not end with the expected `";\\n` tail');
const tailIdx = vpsScript.lastIndexOf(tailMatch[1]);
const newVpsScript = vpsScript.slice(0, tailIdx) + beforeSep + scriptSnippet + vpsScript.slice(tailIdx);
fs.writeFileSync(VPS_SCRIPT, newVpsScript);
console.log('vps script.ts: appended', scriptSnippet.length, 'raw chars');

