// file ends with:  ...<last-inner-iife>})();\n\n})();\n";   (two closes: inner block, then the
// enclosing top-level (() => { ... })(); wrapper). We must insert BEFORE the final, enclosing
// close so our new IIFE runs inside the same scope as $/$$/RM/watch.
const NL2 = '\\n\\n'; // literal 2x "\n" escape pairs, matching the file's own escaping
const outerClose = NL2 + '})();\\n";'; // the enclosing IIFE's close + PAGE_SCRIPT string terminator
const idx = vps.lastIndexOf(outerClose);
if (idx === -1) throw new Error('outer close pattern not found');
const newVps = vps.slice(0, idx) + NL2 + scriptSnippet + outerClose + vps.slice(idx + outerClose.length);
fs.writeFileSync(VPS_SCRIPT, newVps);
console.log('inserted', scriptSnippet.length, 'chars at', idx);
console.log('--- new tail ---');
console.log(newVps.slice(-500));

