const fs = require('fs');
const c = fs.readFileSync('app/nxm/_home/content.ts','utf8');
const m = c.match(/MAIN_HTML = (\"[\s\S]*?\");\n/);
const body = JSON.parse(m[1]);
function sectionAt(offset) {
  const before = body.slice(0, offset);
  const idx = before.lastIndexOf('<section');
  const idMatch = before.slice(idx).match(/id=\"([^\"]+)\"/);
  return idMatch ? idMatch[1] : '(none)';
}
