const { chromium } = require('/opt/nxeon/node_modules/playwright');
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1440, height: 1000 } });
  page.on('pageerror', err => console.log('PAGEERROR', err.message));
  await page.goto('http://localhost:3910/', { waitUntil: 'networkidle', timeout: 60000 });
  await page.waitForTimeout(500);
  // Check state right after load: performance/deploy/products/platform/developers sections should NOT be .in-view yet (far below fold)
  const states = await page.evaluate(() => {
    const ids = ['products','platform','deploy','developers','performance'];
    return Object.fromEntries(ids.map(id => [id, document.getElementById(id)?.classList.contains('in-view')]));
  });
  console.log('initial in-view states', states);
  // count running animations via getAnimations()
  const runningCount = await page.evaluate(() => document.getAnimations().filter(a => a.playState === 'running').length);
  console.log('running animations at load', runningCount);
  // scroll to performance section
  await page.evaluate(() => document.getElementById('performance').scrollIntoView());
  await page.waitForTimeout(600);
  const statesAfter = await page.evaluate(() => {
    const ids = ['products','platform','deploy','developers','performance'];
    return Object.fromEntries(ids.map(id => [id, document.getElementById(id)?.classList.contains('in-view')]));
  });
  console.log('after scrolling to performance', statesAfter);
  await browser.close();
})();
" 2>&1

