.nxm-home .orb{position:relative;width:100%;aspect-ratio:1/.9;contain:strict}
.nxm-home .orb-stage{position:absolute;inset:0}
.nxm-home .orb-svg{position:absolute;inset:0;width:100%;height:100%;overflow:visible}
.nxm-home .orb-svg .st{fill:#CFE0FF;animation:tw 4s ease-in-out infinite}
.nxm-home .orb-svg .rg{fill:none;stroke:rgba(150,170,255,.14);stroke-width:1}
.nxm-home .orb-svg .rg.o2{stroke:rgba(150,170,255,.1)}
.nxm-home .orb-svg .rg.o3{stroke:rgba(150,170,255,.12);stroke-dasharray:2 7}
.nxm-home .orb-svg .cm{fill:none;stroke:url(#orb-beam);stroke-width:1.6;stroke-linecap:round;stroke-dasharray:7 93;filter:drop-shadow(0 0 4px rgba(140,160,255,.9))}
.nxm-home .orb-svg .draw{stroke-dasharray:100;stroke-dashoffset:100;animation:ringIn 1.4s cubic-bezier(.65,0,.35,1) forwards}
.nxm-home .orb-svg .bm{stroke-width:1.4;stroke-linecap:round;opacity:.9}
.nxm-home .orb-svg .pk{fill:#fff;filter:drop-shadow(0 0 5px #9CC9FF)}
.nxm-home .orb-core{position:absolute;left:50%;top:50%;width:112px;height:112px;margin:-56px 0 0 -56px;border-radius:50%;z-index:50;transform:scale(.4);opacity:0;transition:transform 1s cubic-bezier(.16,1,.3,1),opacity .6s}
.nxm-home .orb.in .orb-core{transform:scale(1);opacity:1}
.nxm-home .oc-halo{position:absolute;inset:-46px;border-radius:50%;background:radial-gradient(circle,rgba(70,100,255,.42),rgba(110,70,255,.12) 45%,transparent 70%);animation:halo 4.5s ease-in-out infinite}
.nxm-home .oc-ring{position:absolute;inset:-3px;border-radius:50%;padding:2px;background:conic-gradient(from var(--au-a,0deg),#3EDCF2,#4E8DFF,#9B6BFF,#E04BD6,transparent 70%,#3EDCF2);-webkit-mask:linear-gradient(#000 0 0) content-box,linear-gradient(#000 0 0);-webkit-mask-composite:xor;mask-composite:exclude;animation:auSpin 7s linear infinite}
.nxm-home .oc-glass{position:absolute;inset:0;display:grid;place-items:center;border-radius:50%;background:radial-gradient(circle at 34% 28%,rgba(255,255,255,.2),rgba(30,40,110,.85) 42%,rgba(8,12,34,.98) 75%);box-shadow:inset 0 2px 1px rgba(255,255,255,.25),inset 0 -12px 30px rgba(80,90,255,.35),0 20px 60px -10px rgba(60,80,255,.8)}
.nxm-home .orb-core.flash .oc-glass{animation:flash .9s cubic-bezier(.16,1,.3,1)}
.nxm-home .orb-b{position:absolute;left:0;top:0;width:56px;height:56px;margin:-28px 0 0 -28px;padding:0;border:0;border-radius:50%;cursor:pointer;display:grid;place-items:center;will-change:transform,opacity;
  background:radial-gradient(circle at 34% 28%,rgba(255,255,255,.2),rgba(20,28,70,.92) 46%,rgba(8,12,30,.98) 78%);box-shadow:inset 0 1px 1px rgba(255,255,255,.3),inset 0 -8px 16px rgba(60,80,200,.25),0 0 0 1px rgba(170,185,255,.18),0 12px 26px -10px rgba(0,0,0,.9);opacity:0;-webkit-tap-highlight-color:transparent}
.nxm-home .orb-b img{width:24px;height:24px;filter:brightness(0) invert(1);opacity:.88;transition:filter .3s,opacity .3s,transform .38s cubic-bezier(.16,1,.3,1)}
.nxm-home .orb-b .mono{font:800 .74rem var(--f-display);color:#fff;letter-spacing:-.02em}
.nxm-home .orb-b .nm{position:absolute;top:calc(100% + 8px);left:50%;transform:translateX(-50%);white-space:nowrap;font:600 .74rem var(--f-body);color:var(--muted);pointer-events:none;opacity:0;transition:color .3s,opacity .38s cubic-bezier(.16,1,.3,1)}
.nxm-home .orb-b.front .nm{opacity:1}
.nxm-home .orb-b::after{content:"";position:absolute;inset:-5px;border-radius:50%;border:1.5px solid var(--c);opacity:0;transform:scale(.85);box-shadow:0 0 22px var(--c);transition:opacity .38s cubic-bezier(.16,1,.3,1),transform .38s cubic-bezier(.16,1,.3,1)}
.nxm-home .orb-b.hot img{filter:none;opacity:1;transform:scale(1.08)}
.nxm-home .orb-b.hot .nm{color:#fff}
.nxm-home .orb-b.hot::after{opacity:.9;transform:scale(1)}
.nxm-home .orb-b.dim{filter:grayscale(1) brightness(.55)}
.nxm-home .orb-b:focus-visible{outline:none}
.nxm-home .orb-b:focus-visible::after{opacity:1;transform:scale(1);border-color:#9CC9FF}
@media (max-width:1080px){.nxm-home .orb-wrap{grid-template-columns:1fr}.nxm-home .orb-copy{max-width:640px}.nxm-home .orb-cats{display:flex;flex-wrap:wrap;max-width:none;border:0;gap:6px}.nxm-home .orb-cats button{border:1px solid rgba(255,255,255,.1);border-radius:999px;padding:8px 14px}.nxm-home .orb-cats button:hover,.nxm-home .orb-cats button[aria-pressed="true"]{padding-left:14px}.nxm-home .orb-cats button[aria-pressed="true"]{border-color:rgba(160,150,255,.6);background:rgba(123,92,255,.14)}.nxm-home .orb-cats button em{margin-left:8px}.nxm-home .orb-ind{display:none}}
@media (max-width:640px){.nxm-home .orb-b{width:44px;height:44px;margin:-22px 0 0 -22px}.nxm-home .orb-b img{width:20px;height:20px}.nxm-home .orb-b .nm{display:none}.nxm-home .orb-core{width:84px;height:84px;margin:-42px 0 0 -42px}}
