.nxm-home .gs-xtra a:hover{transform:translateY(-3px);border-color:rgba(170,160,255,.5);box-shadow:inset 0 1px 0 rgba(255,255,255,.1),0 18px 40px -20px rgba(110,90,255,.9)}

