  await page.waitForTimeout(900);
  const perfView = await page.evaluate(() => document.getElementById('performance').classList.contains('in-view'));
  const ringCount = await page.evaluate(() => document.getAnimations().filter(a => a.playState==='running' && a.animationName==='ringPing').length);
  const depCount = await page.evaluate(() => document.getAnimations().filter(a => a.playState==='running' && (a.animationName==='depFill'||a.animationName==='depFillX')).length);
  console.log('performance in-view', perfView, 'ringPing running', ringCount, 'dep* running', depCount);
  // scroll back to top -> orb should go out of view again and pause
  await page.evaluate(() => window.scrollTo(0,0));
  await page.waitForTimeout(900);
  const orbViewAfter = await page.evaluate(() => document.getElementById('orb').classList.contains('in-view'));
  console.log('orb in-view after scrolling back to top', orbViewAfter);
  await browser.close();
})();
